import{_ as i,c as a,o as e,aj as t}from"./chunks/framework.C2N4vG9O.js";const k=JSON.parse('{"title":"Installation","description":"Install Torch-RecHub from PyPI or from source and check that PyTorch can use your device.","frontmatter":{"title":"Installation","description":"Install Torch-RecHub from PyPI or from source and check that PyTorch can use your device."},"headers":[],"relativePath":"guide/install.md","filePath":"en/guide/install.md"}'),n={name:"guide/install.md"};function l(h,s,r,o,p,c){return e(),a("div",null,[...s[0]||(s[0]=[t(`<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to “Installation”">​</a></h1><p>Install from source to follow the tutorials with the sample datasets in the repository. To use Torch-RecHub in an existing training project, install the PyPI package and import <code>torch_rechub</code>.</p><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to “Requirements”">​</a></h2><ul><li>Python 3.10 or later</li><li>PyTorch <code>&gt;=2.6,&lt;3</code></li></ul><p>The package installs NumPy (1.26.4 or later), pandas (2.1 or later) and scikit-learn (1.4 or later). Generative models also use the optional Transformers dependency (<code>&gt;=4.57.3,&lt;5</code>).</p><h2 id="install-torch-rechub" tabindex="-1">Install Torch-RecHub <a class="header-anchor" href="#install-torch-rechub" aria-label="Permalink to “Install Torch-RecHub”">​</a></h2><p>On a CPU, choose either the release package or a source installation. For a GPU or NPU, first install a compatible PyTorch build in the environment where you will run Torch-RecHub. <a href="#install-pytorch-for-your-device">PyTorch device examples</a></p><h3 id="in-an-existing-project" tabindex="-1">In an existing project <a class="header-anchor" href="#in-an-existing-project" aria-label="Permalink to “In an existing project”">​</a></h3><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> torch-rechub</span></span></code></pre></div><h3 id="optional-features" tabindex="-1">Optional features <a class="header-anchor" href="#optional-features" aria-label="Permalink to “Optional features”">​</a></h3><p>The base installation can train models such as DeepFM and DSSM. Add an extra when you need to draw a diagram, export to ONNX or search an index. The commands below install the release package. In a source checkout, use the extra name with uv, for example <code>uv sync --extra visualization</code>.</p><table tabindex="0"><thead><tr><th>Feature</th><th>Installation command</th></tr></thead><tbody><tr><td>Generative models</td><td><code>python -m pip install &quot;torch-rechub[generative]&quot;</code></td></tr><tr><td>Parquet streaming</td><td><code>python -m pip install &quot;torch-rechub[bigdata]&quot;</code></td></tr><tr><td>ONNX export and quantization</td><td><code>python -m pip install &quot;torch-rechub[onnx]&quot;</code></td></tr><tr><td>Model diagrams</td><td><code>python -m pip install &quot;torch-rechub[visualization]&quot;</code></td></tr><tr><td>Experiment tracking</td><td><code>python -m pip install &quot;torch-rechub[tracking]&quot;</code></td></tr><tr><td>Vector search</td><td><code>python -m pip install &quot;torch-rechub[annoy]&quot;</code>. Choose <code>annoy</code>, <code>faiss</code> or <code>milvus</code> to match your backend.</td></tr><tr><td>Tests, formatters and type checking</td><td><code>python -m pip install &quot;torch-rechub[dev]&quot;</code></td></tr><tr><td>All optional features</td><td><code>python -m pip install &quot;torch-rechub[all]&quot;</code></td></tr></tbody></table><p>To render model diagrams, install Graphviz on the system as well. The <code>dot</code> executable must be on your path.</p><p>For a single script, you can install its extras as part of the command with <code>uv run --extra &lt;name&gt; python &lt;script.py&gt;</code>. Repeat <code>--extra</code> when a script needs more than one group.</p><h3 id="from-source" tabindex="-1">From source <a class="header-anchor" href="#from-source" aria-label="Permalink to “From source”">​</a></h3><p>The checkout includes example scripts and sample data. These commands download it and create a project environment in <code>.venv</code>.</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Install uv if it is not already available.</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> uv</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Clone the repository.</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/datawhalechina/torch-rechub.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> torch-rechub</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Create .venv, install locked dependencies and install the project in editable mode.</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sync</span></span></code></pre></div><p>If your active environment already has a device-specific PyTorch build, use <code>uv pip install -e .</code> in place of the final <code>uv sync</code>. Run the examples with that environment&#39;s <code>python</code>.</p><h2 id="set-up-a-contribution" tabindex="-1">Set up a contribution <a class="header-anchor" href="#set-up-a-contribution" aria-label="Permalink to “Set up a contribution”">​</a></h2><p>To submit a pull request, fork the repository on GitHub and clone your fork. Replace <code>YOUR_USERNAME</code> below with your GitHub username.</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1. Fork the project and clone your fork.</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/YOUR_USERNAME/torch-rechub.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> torch-rechub</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2. Install dependencies in the project environment.</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sync</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 3. Run the tests against the editable installation.</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pytest</span></span></code></pre></div><h2 id="install-pytorch-for-your-device" tabindex="-1">Install PyTorch for your device <a class="header-anchor" href="#install-pytorch-for-your-device" aria-label="Permalink to “Install PyTorch for your device”">​</a></h2><p>Choose the build for your hardware and driver.</p><ul><li><strong>NVIDIA GPU.</strong> Select a CUDA build compatible with the installed driver. <a href="https://pytorch.org/get-started/locally/" target="_blank" rel="noreferrer">PyTorch installation guide</a></li><li><strong>AMD GPU.</strong> Find the ROCm packages for your GPU model. <a href="https://rocm.docs.amd.com/projects/radeon-ryzen/en/latest/" target="_blank" rel="noreferrer">AMD ROCm documentation</a></li><li><strong>Huawei Ascend NPU.</strong> Install and load CANN, then choose the matching PyTorch and <code>torch-npu</code> versions. <a href="https://github.com/Ascend/pytorch/blob/master/COMPATIBILITY.md" target="_blank" rel="noreferrer">Ascend compatibility table</a></li></ul><p>The commands below illustrate one setup for each device. Run the one that matches your machine in the active Python environment. With uv, substitute <code>uv pip</code> for <code>python -m pip</code>.</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># CPU-only build for Linux or Windows</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> torch</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --index-url</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://download.pytorch.org/whl/cpu</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># NVIDIA GPU example using CUDA 12.6</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> torch</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --index-url</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://download.pytorch.org/whl/cu126</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># AMD GPU example for the Ryzen AI Max+ 395 (gfx1151)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --index-url</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://repo.amd.com/rocm/whl/gfx1151/</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;rocm[libraries,devel]&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> torch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> torchvision</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> torchaudio</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Huawei Ascend NPU, if the default package versions match the installed CANN version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> torch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> torch-npu</span></span></code></pre></div><p>Use <code>device=&quot;cuda:0&quot;</code> in the trainer for the first NVIDIA or AMD GPU. For the first Ascend NPU, import <code>torch_npu</code> and use <code>device=&quot;npu:0&quot;</code>.</p><h2 id="verify-the-installation" tabindex="-1">Verify the installation <a class="header-anchor" href="#verify-the-installation" aria-label="Permalink to “Verify the installation”">​</a></h2><p>Print the package version from the environment where you installed Torch-RecHub.</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;import torch_rechub; print(torch_rechub.__version__)&quot;</span></span></code></pre></div><p>If you use an accelerator, choose the command for your device and check that PyTorch can create a tensor on it.</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># NVIDIA CUDA or AMD ROCm</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;import torch; print(torch.zeros(1, device=&#39;cuda:0&#39;).device)&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Huawei Ascend: load the CANN environment first.</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;import torch, torch_npu; print(torch.zeros(1, device=&#39;npu:0&#39;).device)&quot;</span></span></code></pre></div><p>If Python cannot find <code>torch_rechub</code> after a source installation, run <code>uv run python</code> from the repository root to use the project environment. If the device check fails, look up the full error together with your accelerator model, driver or CANN version, and PyTorch version. <a href="/torch-rechub/community/faq.html">FAQ</a> · <a href="https://github.com/datawhalechina/torch-rechub/issues" target="_blank" rel="noreferrer">GitHub issues</a></p>`,33)])])}const u=i(n,[["render",l]]);export{k as __pageData,u as default};
